#include "stdlib/stats/base/ndarray/sstdev.h"
#include "stdlib/stats/strided/sstdev.h"
#include "stdlib/ndarray/ctor.h"
#include "stdlib/blas/base/shared.h"

/**
* Computes the standard deviation of a one-dimensional single-precision floating-point ndarray.
*
* @param arrays    list containing an input ndarray and a zero-dimensional ndarray specifying the degrees of freedom adjustment
* @return          standard deviation
*/
float stdlib_stats_sstdev( const struct ndarray *arrays[] ) {
	const struct ndarray *x = arrays[ 0 ];
	const struct ndarray *correction = arrays[ 1 ];

	float c;

	// For zero-dimensional arrays, `stdlib_ndarray_iget_float32` returns the first (and only) indexed element, regardless of the supplied index:
	stdlib_ndarray_iget_float32( correction, 0, &c );

	return API_SUFFIX(stdlib_strided_sstdev_ndarray)( stdlib_ndarray_dimension( x, 0 ), c, (const float *)stdlib_ndarray_data( x ), stdlib_ndarray_stride_elements( x, 0 ), stdlib_ndarray_offset_elements( x ) );
}
